class Solution:
    def flightStatus(self, flights, passengers):
        cap = {f[0]: f[1] for f in flights}
        res = []
        for pid, fid, t in passengers:
            earlier = sum(1 for _, f2, t2 in passengers if f2 == fid and t2 < t)
            res.append([pid, "Confirmed" if earlier < cap[fid] else "Waitlist"])
        return sorted(res)

