class Solution {
public:
    vector<vector<string>> flightStatus(vector<vector<int>>& flights,
                                        vector<vector<string>>& passengers) {
        unordered_map<int,int> cap;
        for (auto& f : flights) cap[f[0]] = f[1];
        vector<array<string,2>> tmp;
        for (auto& p : passengers) {
            int fid = stoi(p[1]);
            long long cnt = 0;
            for (auto& q : passengers)
                if (q[1] == p[1] && q[2] < p[2]) cnt++;
            tmp.push_back({p[0], cnt < cap[fid] ? "Confirmed" : "Waitlist"});
        }
        sort(tmp.begin(), tmp.end());
        vector<vector<string>> res;
        for (auto& r : tmp) res.push_back({r[0], r[1]});
        return res;
    }
};

