class Solution {
    public List<List<String>> flightStatus(int[][] flights, String[][] passengers) {
        Map<Integer, Integer> cap = new HashMap<>();
        for (int[] f : flights) cap.put(f[0], f[1]);
        int n = passengers.length;
        String[][] tmp = new String[n][2];
        for (int i = 0; i < n; i++) {
            int fid = Integer.parseInt(passengers[i][1]);
            long cnt = 0;
            for (int j = 0; j < n; j++)
                if (passengers[j][1].equals(passengers[i][1])
                    && passengers[j][2].compareTo(passengers[i][2]) < 0) cnt++;
            tmp[i][0] = passengers[i][0];
            tmp[i][1] = cnt < cap.get(fid) ? "Confirmed" : "Waitlist";
        }
        Arrays.sort(tmp, (a, b) -> Integer.compare(Integer.parseInt(a[0]), Integer.parseInt(b[0])));
        List<List<String>> res = new ArrayList<>();
        for (String[] r : tmp) res.add(Arrays.asList(r[0], r[1]));
        return res;
    }
}

