class Solution {
    public List<List<String>> flightStatus(int[][] flights, String[][] passengers) {
        Map<Integer, Integer> cap = new HashMap<>();
        for (int[] f : flights) cap.put(f[0], f[1]);
        String[][] recs = new String[passengers.length][3];
        for (int i = 0; i < passengers.length; i++)
            recs[i] = new String[]{passengers[i][1], passengers[i][2], passengers[i][0]};
        Arrays.sort(recs, (a, b) -> !a[0].equals(b[0])
                ? Integer.parseInt(a[0]) - Integer.parseInt(b[0])
                : a[1].compareTo(b[1]));
        Map<Integer, Integer> seen = new HashMap<>();
        List<List<String>> out = new ArrayList<>();
        for (String[] r : recs) {
            int fid = Integer.parseInt(r[0]);
            int rank = seen.merge(fid, 1, Integer::sum) - 1;
            out.add(Arrays.asList(r[2], rank < cap.get(fid) ? "Confirmed" : "Waitlist"));
        }
        out.sort(Comparator.comparingInt(a -> Integer.parseInt(a.get(0))));
        return out;
    }
}

