var flightStatus = function(flights, passengers) {
    const cap = new Map(flights.map(f => [f[0], f[1]]));
    const order = [...passengers].sort((a, b) =>
        a[1] - b[1] || (a[2] < b[2] ? -1 : 1));
    const seen = new Map();
    const res = [];
    for (const [pid, fid, t] of order) {
        const rank = seen.get(fid) || 0;
        seen.set(fid, rank + 1);
        res.push([pid, rank < cap.get(fid) ? 'Confirmed' : 'Waitlist']);
    }
    return res.sort((a, b) => a[0] - b[0]);
};
